import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ExclamationTriangleIcon, InformationCircleIcon, DocumentDuplicateIcon } from '@heroicons/react/24/outline';
import { useNotification } from '../../hooks/useNotification';

const DMARCConfigurationStep = ({ domainId, data, onChange, errors, onNext, onPrev, canGoBack, saving }) => {
  const [dmarcPolicy, setDmarcPolicy] = useState(data.dmarcPolicy || 'none');
  const [percentage, setPercentage] = useState(data.percentage || '100');
  const [reportingEmail, setReportingEmail] = useState(data.reportingEmail || '');
  const [forensicEmail, setForensicEmail] = useState(data.forensicEmail || '');
  const [spfAlignment, setSpfAlignment] = useState(data.spfAlignment || 'relaxed');
  const [dkimAlignment, setDkimAlignment] = useState(data.dkimAlignment || 'relaxed');
  const [dmarcRecord, setDmarcRecord] = useState(data.dmarcRecord || '');
  const [reportFormat, setReportFormat] = useState(data.reportFormat || 'afrf');
  const [reportInterval, setReportInterval] = useState(data.reportInterval || '86400');
  const { showNotification } = useNotification();

  // Políticas DMARC
  const dmarcPolicies = [
    {
      value: 'none',
      label: 'None (Monitoreo)',
      description: 'No tomar acción, solo generar reportes. Recomendado para empezar.',
      risk: 'low',
      color: 'green'
    },
    {
      value: 'quarantine',
      label: 'Quarantine (Cuarentena)',
      description: 'Marcar correos fallidos como spam o moverlos a cuarentena.',
      risk: 'medium',
      color: 'yellow'
    },
    {
      value: 'reject',
      label: 'Reject (Rechazar)',
      description: 'Rechazar completamente los correos que fallen la verificación.',
      risk: 'high',
      color: 'red'
    }
  ];

  // Opciones de alineación
  const alignmentOptions = [
    {
      value: 'relaxed',
      label: 'Relajada',
      description: 'Permite subdominios (ej: mail.example.com para example.com)'
    },
    {
      value: 'strict',
      label: 'Estricta',
      description: 'Requiere coincidencia exacta del dominio'
    }
  ];

  // Intervalos de reporte
  const reportIntervals = [
    { value: '86400', label: 'Diario (24 horas)' },
    { value: '604800', label: 'Semanal (7 días)' },
    { value: '2592000', label: 'Mensual (30 días)' }
  ];

  useEffect(() => {
    generateDMARCRecord();
  }, [dmarcPolicy, percentage, reportingEmail, forensicEmail, spfAlignment, dkimAlignment, reportFormat, reportInterval]);

  useEffect(() => {
    // Actualizar datos del paso cuando cambien los valores
    onChange('dmarcPolicy', dmarcPolicy);
    onChange('percentage', percentage);
    onChange('reportingEmail', reportingEmail);
    onChange('forensicEmail', forensicEmail);
    onChange('spfAlignment', spfAlignment);
    onChange('dkimAlignment', dkimAlignment);
    onChange('dmarcRecord', dmarcRecord);
    onChange('reportFormat', reportFormat);
    onChange('reportInterval', reportInterval);
  }, [dmarcPolicy, percentage, reportingEmail, forensicEmail, spfAlignment, dkimAlignment, dmarcRecord, reportFormat, reportInterval]);

  const generateDMARCRecord = () => {
    let record = `v=DMARC1; p=${dmarcPolicy}`;

    // Agregar porcentaje si no es 100%
    if (percentage !== '100') {
      record += `; pct=${percentage}`;
    }

    // Agregar email para reportes agregados
    if (reportingEmail) {
      record += `; rua=mailto:${reportingEmail}`;
    }

    // Agregar email para reportes forenses
    if (forensicEmail) {
      record += `; ruf=mailto:${forensicEmail}`;
    }

    // Agregar alineación SPF si no es relajada
    if (spfAlignment === 'strict') {
      record += `; aspf=s`;
    }

    // Agregar alineación DKIM si no es relajada
    if (dkimAlignment === 'strict') {
      record += `; adkim=s`;
    }

    // Agregar formato de reporte si no es el por defecto
    if (reportFormat !== 'afrf') {
      record += `; fo=${reportFormat}`;
    }

    // Agregar intervalo de reporte si no es diario
    if (reportInterval !== '86400') {
      record += `; ri=${reportInterval}`;
    }

    setDmarcRecord(record);
  };

  const copyToClipboard = async (text, label) => {
    try {
      await navigator.clipboard.writeText(text);
      showNotification(`${label} copiado al portapapeles`, 'success');
    } catch (error) {
      console.error('Error copying to clipboard:', error);
      showNotification('Error al copiar al portapapeles', 'error');
    }
  };

  const validateDMARCConfig = () => {
    const issues = [];

    if (!dmarcPolicy) {
      issues.push('Debe seleccionar una política DMARC');
    }

    if (percentage < 1 || percentage > 100) {
      issues.push('El porcentaje debe estar entre 1 y 100');
    }

    if (reportingEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(reportingEmail)) {
      issues.push('El email para reportes agregados no es válido');
    }

    if (forensicEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(forensicEmail)) {
      issues.push('El email para reportes forenses no es válido');
    }

    if (dmarcRecord.length > 255) {
      issues.push('El registro DMARC es demasiado largo (máximo 255 caracteres)');
    }

    return issues;
  };

  const validationIssues = validateDMARCConfig();
  const isValid = validationIssues.length === 0;
  const selectedPolicy = dmarcPolicies.find(p => p.value === dmarcPolicy);

  const handleNext = () => {
    if (isValid) {
      onNext();
    } else {
      showNotification('Por favor corrige los errores en la configuración DMARC', 'error');
    }
  };

  return (
    <div className="space-y-6">
      {/* Introducción */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <InformationCircleIcon className="h-5 w-5 text-blue-400" />
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">
              Configuración de Política DMARC
            </h3>
            <div className="mt-2 text-sm text-blue-700">
              <p>
                DMARC utiliza SPF y DKIM para determinar qué hacer con los correos que
                no pasan la autenticación. Comienza con "none" para monitorear sin afectar la entrega.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Selección de política */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Política DMARC</h3>
        <p className="text-sm text-gray-600 mb-4">
          Selecciona qué acción tomar con los correos que fallen la verificación DMARC:
        </p>

        <div className="space-y-3">
          {dmarcPolicies.map(policy => (
            <label key={policy.value} className={`
              flex items-start p-4 border-2 rounded-lg cursor-pointer transition-colors
              ${
                dmarcPolicy === policy.value
                  ? `border-${policy.color}-500 bg-${policy.color}-50`
                  : 'border-gray-200 hover:bg-gray-50'
              }
            `}>
              <input
                type="radio"
                name="dmarcPolicy"
                value={policy.value}
                checked={dmarcPolicy === policy.value}
                onChange={(e) => setDmarcPolicy(e.target.value)}
                className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 mt-0.5"
              />
              <div className="ml-3 flex-1">
                <div className="flex items-center justify-between">
                  <div className="text-sm font-medium text-gray-900">{policy.label}</div>
                  <span className={`
                    inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                    ${
                      policy.risk === 'low'
                        ? 'bg-green-100 text-green-800'
                        : policy.risk === 'medium'
                        ? 'bg-yellow-100 text-yellow-800'
                        : 'bg-red-100 text-red-800'
                    }
                  `}>
                    Riesgo {policy.risk === 'low' ? 'Bajo' : policy.risk === 'medium' ? 'Medio' : 'Alto'}
                  </span>
                </div>
                <div className="text-sm text-gray-600 mt-1">{policy.description}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Configuración de porcentaje */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Porcentaje de Aplicación</h3>
        <p className="text-sm text-gray-600 mb-4">
          Especifica qué porcentaje de correos debe ser sujeto a la política DMARC:
        </p>

        <div className="max-w-md">
          <label htmlFor="percentage" className="block text-sm font-medium text-gray-700 mb-2">
            Porcentaje (%)
          </label>
          <div className="flex items-center space-x-3">
            <input
              type="range"
              id="percentage"
              min="1"
              max="100"
              value={percentage}
              onChange={(e) => setPercentage(e.target.value)}
              className="flex-1 h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
            />
            <div className="w-16">
              <input
                type="number"
                min="1"
                max="100"
                value={percentage}
                onChange={(e) => setPercentage(e.target.value)}
                className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
              />
            </div>
          </div>
          <p className="mt-1 text-xs text-gray-500">
            Comienza con un porcentaje bajo (ej: 25%) y aumenta gradualmente
          </p>
        </div>
      </div>

      {/* Configuración de reportes */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Configuración de Reportes</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label htmlFor="reportingEmail" className="block text-sm font-medium text-gray-700 mb-2">
              Email para Reportes Agregados (RUA)
            </label>
            <input
              type="email"
              id="reportingEmail"
              value={reportingEmail}
              onChange={(e) => setReportingEmail(e.target.value)}
              placeholder="reportes@tudominio.com"
              className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
            />
            <p className="mt-1 text-xs text-gray-500">
              Recibirás reportes diarios con estadísticas de autenticación
            </p>
          </div>

          <div>
            <label htmlFor="forensicEmail" className="block text-sm font-medium text-gray-700 mb-2">
              Email para Reportes Forenses (RUF)
            </label>
            <input
              type="email"
              id="forensicEmail"
              value={forensicEmail}
              onChange={(e) => setForensicEmail(e.target.value)}
              placeholder="forense@tudominio.com"
              className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
            />
            <p className="mt-1 text-xs text-gray-500">
              Recibirás muestras de correos que fallen la verificación
            </p>
          </div>
        </div>

        <div className="max-w-md">
          <label htmlFor="reportInterval" className="block text-sm font-medium text-gray-700 mb-2">
            Intervalo de Reportes
          </label>
          <select
            id="reportInterval"
            value={reportInterval}
            onChange={(e) => setReportInterval(e.target.value)}
            className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
          >
            {reportIntervals.map(interval => (
              <option key={interval.value} value={interval.value}>
                {interval.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Configuración de alineación */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Alineación de Identificadores</h3>
        <p className="text-sm text-gray-600 mb-4">
          Configura qué tan estricta debe ser la verificación de dominios:
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <h4 className="text-sm font-medium text-gray-900 mb-3">Alineación SPF</h4>
            <div className="space-y-2">
              {alignmentOptions.map(option => (
                <label key={option.value} className="flex items-start p-2 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                  <input
                    type="radio"
                    name="spfAlignment"
                    value={option.value}
                    checked={spfAlignment === option.value}
                    onChange={(e) => setSpfAlignment(e.target.value)}
                    className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 mt-0.5"
                  />
                  <div className="ml-3">
                    <div className="text-sm font-medium text-gray-900">{option.label}</div>
                    <div className="text-xs text-gray-600">{option.description}</div>
                  </div>
                </label>
              ))}
            </div>
          </div>

          <div>
            <h4 className="text-sm font-medium text-gray-900 mb-3">Alineación DKIM</h4>
            <div className="space-y-2">
              {alignmentOptions.map(option => (
                <label key={option.value} className="flex items-start p-2 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                  <input
                    type="radio"
                    name="dkimAlignment"
                    value={option.value}
                    checked={dkimAlignment === option.value}
                    onChange={(e) => setDkimAlignment(e.target.value)}
                    className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 mt-0.5"
                  />
                  <div className="ml-3">
                    <div className="text-sm font-medium text-gray-900">{option.label}</div>
                    <div className="text-xs text-gray-600">{option.description}</div>
                  </div>
                </label>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Registro DMARC generado */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Registro DMARC Generado</h3>

        <div className="bg-gray-50 border border-gray-200 rounded-md p-3 mb-4">
          <div className="text-sm text-gray-600 mb-2">Tipo: TXT</div>
          <div className="text-sm text-gray-600 mb-2">Nombre: _dmarc (o _dmarc.tudominio.com)</div>
          <div className="text-sm text-gray-600 mb-2">Valor:</div>
          <div className="font-mono text-sm bg-white border border-gray-200 rounded p-2 break-all">
            {dmarcRecord}
          </div>
          <button
            onClick={() => copyToClipboard(dmarcRecord, 'Registro DMARC')}
            className="mt-2 inline-flex items-center text-sm text-primary-600 hover:text-primary-800"
          >
            <DocumentDuplicateIcon className="h-4 w-4 mr-1" />
            Copiar registro
          </button>
        </div>

        {/* Validación */}
        {validationIssues.length > 0 ? (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3">
            <div className="flex">
              <ExclamationTriangleIcon className="h-5 w-5 text-red-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-red-800">Problemas Detectados</h4>
                <ul className="mt-2 text-sm text-red-700 list-disc list-inside">
                  {validationIssues.map((issue, index) => (
                    <li key={index}>{issue}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-green-50 border border-green-200 rounded-lg p-3">
            <div className="flex">
              <CheckCircleIcon className="h-5 w-5 text-green-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-green-800">Registro DMARC Válido</h4>
                <p className="mt-1 text-sm text-green-700">
                  El registro DMARC está correctamente formateado y listo para usar.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Recomendaciones */}
      {selectedPolicy && (
        <div className={`
          border rounded-lg p-4
          ${
            selectedPolicy.risk === 'low'
              ? 'bg-green-50 border-green-200'
              : selectedPolicy.risk === 'medium'
              ? 'bg-yellow-50 border-yellow-200'
              : 'bg-red-50 border-red-200'
          }
        `}>
          <div className="flex">
            <InformationCircleIcon className={`
              h-5 w-5 flex-shrink-0
              ${
                selectedPolicy.risk === 'low'
                  ? 'text-green-400'
                  : selectedPolicy.risk === 'medium'
                  ? 'text-yellow-400'
                  : 'text-red-400'
              }
            `} />
            <div className="ml-3">
              <h3 className={`
                text-sm font-medium
                ${
                  selectedPolicy.risk === 'low'
                    ? 'text-green-800'
                    : selectedPolicy.risk === 'medium'
                    ? 'text-yellow-800'
                    : 'text-red-800'
                }
              `}>
                Recomendaciones para Política "{selectedPolicy.label}"
              </h3>
              <div className={`
                mt-2 text-sm
                ${
                  selectedPolicy.risk === 'low'
                    ? 'text-green-700'
                    : selectedPolicy.risk === 'medium'
                    ? 'text-yellow-700'
                    : 'text-red-700'
                }
              `}>
                {selectedPolicy.value === 'none' && (
                  <ul className="list-disc list-inside space-y-1">
                    <li>Ideal para comenzar y monitorear el tráfico de correo</li>
                    <li>Revisa los reportes durante al menos 2 semanas</li>
                    <li>Una vez que tengas confianza, considera cambiar a "quarantine"</li>
                  </ul>
                )}
                {selectedPolicy.value === 'quarantine' && (
                  <ul className="list-disc list-inside space-y-1">
                    <li>Asegúrate de que SPF y DKIM estén correctamente configurados</li>
                    <li>Comienza con un porcentaje bajo (25%) y aumenta gradualmente</li>
                    <li>Monitorea los reportes para detectar correos legítimos afectados</li>
                  </ul>
                )}
                {selectedPolicy.value === 'reject' && (
                  <ul className="list-disc list-inside space-y-1">
                    <li>Solo usa esta política después de probar "quarantine" exitosamente</li>
                    <li>Asegúrate de que todos los servicios de correo legítimos estén configurados</li>
                    <li>Ten un plan de respaldo en caso de problemas de entrega</li>
                  </ul>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Error de validación */}
      {errors.dmarcPolicy && (
        <div className="text-sm text-red-600">
          {errors.dmarcPolicy}
        </div>
      )}

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onPrev}
          disabled={!canGoBack}
          className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <button
          onClick={handleNext}
          disabled={saving || !isValid}
          className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {saving ? 'Guardando...' : 'Siguiente'}
        </button>
      </div>
    </div>
  );
};

export default DMARCConfigurationStep;
